/**
 * Type definition for fluent ExitLoop API
 */
type ExitLoopType = Now.Internal.WithID<{
    annotation?: string
}>

/**
 * ExitLoop function used in Flow Logic
 * @param params - object containing:
 *   - $id - Unique identifier for the record, typically using `Now.ID["value"]`
 *   - annotation - Optional annotation/description for the Exit Loop branch
 * @returns void
 */
export declare function ExitLoop<T extends ExitLoopType>(exitLoop: T): { type: 'exitloop' }
